package com.mytimelogger.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.webkit.JavascriptInterface;
import androidx.core.app.*;import androidx.core.content.ContextCompat;import org.json.*;import java.net.URI;import java.text.SimpleDateFormat;import java.util.*;

public final class SleepAutomationBridge {
    public static final String JAVASCRIPT_NAME="MTLSleepAutomation";
    interface Actions { String status(); boolean enable(); void disable(); boolean test(); void cancel(); boolean configure(String url,String token); boolean authorize(String permission); void clearConfiguration(); }
    static final class DefaultActions implements Actions {
        final Context c,launchContext; final SleepAutomationSecretStore secrets;
        DefaultActions(Context context){launchContext=context;c=context.getApplicationContext();secrets=new SleepAutomationSecretStore(c);}
        boolean accessibility(){return SleepAutomationAccessibility.isEnabled(c);}
        String version(){try{return c.getPackageManager().getPackageInfo("com.huawei.health",0).versionName;}catch(Exception e){return "missing";}}
        public String status(){try{boolean media=Build.VERSION.SDK_INT<33||ContextCompat.checkSelfPermission(c,Manifest.permission.READ_MEDIA_IMAGES)==PackageManager.PERMISSION_GRANTED;PowerManager power=(PowerManager)c.getSystemService(Context.POWER_SERVICE);JSONObject permissions=new JSONObject().put("accessibility",accessibility()).put("notifications",NotificationManagerCompat.from(c).areNotificationsEnabled()).put("media",media).put("battery",power.isIgnoringBatteryOptimizations(c.getPackageName()));JSONArray history=new JSONArray();SleepAutomationStateStore store=new SleepAutomationStateStore(c);List<SleepAutomationSnapshot> rows=store.history();for(int i=0;i<Math.min(7,rows.size());i++){SleepAutomationSnapshot s=rows.get(i);history.put(new JSONObject().put("stage",s.stage).put("result","SUCCESS".equals(s.stage)?"success":"FAILED".equals(s.stage)?"failure":"running").put("reason",s.reason));}SharedPreferences p=c.getSharedPreferences(SleepAutomationRescheduleReceiver.PREFS,Context.MODE_PRIVATE);long next=p.getLong(SleepAutomationRescheduleReceiver.NEXT,0),retry=store.nextRetryAt();SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.CHINA);f.setTimeZone(SleepAutomationScheduler.BEIJING);JSONObject out=new JSONObject().put("buildId",SleepAutomationRunnerService.AUTOMATION_REVISION).put("enabled",p.getBoolean(SleepAutomationRescheduleReceiver.ENABLED,false)).put("configured",secrets.read()!=null).put("permissions",permissions).put("huaweiVersion",version()).put("history",history).put("lastStartSource",store.lastStartSource()).put("nextRunAt",next>0?f.format(new Date(next)):"").put("nextRetryAt",retry>0?f.format(new Date(retry)):"");if(rows.size()>0)out.put("stage",rows.get(0).stage).put("reason",rows.get(0).reason);return out.toString();}catch(Exception e){return "{\"enabled\":false,\"error\":\"native_error\"}";}}
        public boolean enable(){long now=System.currentTimeMillis(),next=SleepAutomationScheduler.next840(now);SleepAutomationRescheduleReceiver.setEnabled(c,true);c.getSharedPreferences(SleepAutomationRescheduleReceiver.PREFS,Context.MODE_PRIVATE).edit().putLong(SleepAutomationRescheduleReceiver.NEXT,next).apply();SleepAutomationAlarmReceiver.scheduleNext(c,now);return true;}
        public void disable(){cancel();SleepAutomationRescheduleReceiver.setEnabled(c,false);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.cancel(SleepAutomationAlarmReceiver.pending(c));a.cancel(SleepAutomationRunnerService.retryPending(c));}
        public boolean test(){try{ContextCompat.startForegroundService(c,new Intent(c,SleepAutomationRunnerService.class).setAction(SleepAutomationRunnerService.TEST_ACTION).putExtra(SleepAutomationRunnerService.EXTRA_STAGE,"PENDING"));return true;}catch(Exception e){return false;}}
        public void cancel(){c.stopService(new Intent(c,SleepAutomationRunnerService.class));HuaweiSleepAutomationService.cancel();}
        public boolean configure(String u,String t){boolean debug=(c.getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0;if(t==null||t.isEmpty()||!serverUrlAllowed(u,debug))return false;secrets.save(u,t);return secrets.read()!=null;}
        private void open(Intent i){if(!(launchContext instanceof Activity))i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);launchContext.startActivity(i);}
        public boolean authorize(String key){try{if("accessibility".equals(key)){open(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));return true;}if("notifications".equals(key)){if(Build.VERSION.SDK_INT>=33&&launchContext instanceof Activity)ActivityCompat.requestPermissions((Activity)launchContext,new String[]{Manifest.permission.POST_NOTIFICATIONS},842);else open(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,c.getPackageName()));return true;}if("media".equals(key)){if(Build.VERSION.SDK_INT>=33&&launchContext instanceof Activity)ActivityCompat.requestPermissions((Activity)launchContext,new String[]{Manifest.permission.READ_MEDIA_IMAGES},843);else open(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+c.getPackageName())));return true;}if("battery".equals(key)){open(new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,Uri.parse("package:"+c.getPackageName())));return true;}return false;}catch(Exception e){return false;}}
        public void clearConfiguration(){secrets.clear();}
    }
    static boolean serverUrlAllowed(String raw,boolean debug){try{URI u=URI.create(raw);String scheme=u.getScheme(),host=u.getHost();if(host==null||u.getUserInfo()!=null)return false;if("https".equalsIgnoreCase(scheme))return true;if(!"http".equalsIgnoreCase(scheme))return false;return debug||privateHttpHost(host);}catch(Exception ignored){return false;}}
    private static boolean privateHttpHost(String host){String h=host.toLowerCase(Locale.ROOT);return "localhost".equals(h)||"127.0.0.1".equals(h)||"::1".equals(h)||h.startsWith("10.")||h.startsWith("192.168.")||h.matches("172\\.(1[6-9]|2[0-9]|3[01])\\..+");}
    private final Actions actions; SleepAutomationBridge(Context c){this(new DefaultActions(c));} SleepAutomationBridge(Actions a){actions=a;}
    @JavascriptInterface public String status(){return actions.status();}@JavascriptInterface public boolean enable(){return actions.enable();}@JavascriptInterface public void disable(){actions.disable();}@JavascriptInterface public boolean test(){return actions.test();}@JavascriptInterface public void cancel(){actions.cancel();}@JavascriptInterface public boolean configure(String u,String t){return actions.configure(u,t);}@JavascriptInterface public boolean authorize(String p){return actions.authorize(p);}@JavascriptInterface public void clearConfiguration(){actions.clearConfiguration();}
}
